steps.data:
/**
 * ILANEL POC — Ross Gardam clone
 *
 * Values taken from rossgardam.com.au's live stylesheet, not estimated:
 *   .article__content p  font-size 1.8rem / weight 300 / line-height 1.35
 *   .article__head       margin-bottom 4.1rem
 *   .section-details     padding 0 0 18rem
 *   .shell               padding 0 3rem (mobile 2rem)
 *   letter-spacing       .005 / .01 / .02 / .06 / .08em
 *   body                 #fff bg, #000 text, ABCFavorit
 *   font-weights         300 / 400 / 600 only
 *
 * RG use ABCFavorit (grotesque) + Lyon Display (serif wordmark and
 * product names). Both are licensed and cannot be redistributed, so this
 * substitutes Inter and a Didone serif. Swap in the licensed faces for
 * production and the match tightens further.
 *
 * RG set html{font-size:62.5%} so 1rem = 10px. We do the same, which is
 * why the values above transfer directly.
 */

html {
  font-size: 62.5%;
}

:root {
  --rg-ink: #000;
  --rg-bg: #fff;
  --rg-tile: #eee;
  --rg-tile-alt: #f4f4f4;
  --rg-rule: #d5d5d5;
  --rg-muted: #767676;
  --rg-accent: #8a6d3b;

  --rg-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
  --rg-serif: 'Playfair Display', 'Times New Roman', serif;

  --rg-shell: 3rem;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--rg-bg);
  color: var(--rg-ink);
  font-family: var(--rg-sans);
  font-weight: 400;
  font-size: 1.5rem;
  line-height: 1.5;
  text-align: left;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.rg-shell {
  max-width: 168rem;
  margin: 0 auto;
  padding: 0 var(--rg-shell);
}

/* --- Header --------------------------------------------------------------- */

.rg-header {
  padding: 3.2rem 0 2.8rem;
}

.rg-header__inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  padding: 0 var(--rg-shell);
}

.rg-navbtn {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.5rem;
  width: 2.4rem;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
}

.rg-navbtn span {
  display: block;
  height: 1px;
  background: var(--rg-ink);
}

.rg-navbtn span:nth-child(2) {
  width: 70%;
}

.rg-header__logo {
  grid-column: 2;
  margin: 0;
  font-family: var(--rg-serif);
  font-size: 2.9rem;
  font-weight: 400;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  line-height: 1;
  text-indent: 0.18em;
}

.rg-utilities {
  grid-column: 3;
  display: flex;
  justify-content: flex-end;
  gap: 1.8rem;
}

/* --- Hero ----------------------------------------------------------------- */

.rg-hero {
  width: 100%;
  height: 62vh;
  max-height: 68rem;
  min-height: 38rem;
  background-color: var(--rg-tile);
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
}

/* --- Breadcrumbs ---------------------------------------------------------- */

.rg-breadcrumbs {
  padding: 2.6rem 0;
}

.rg-breadcrumbs--inline {
  padding: 0 0 3.5rem;
}

.ilanel-breadcrumbs ol {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 1.1rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.ilanel-breadcrumbs li + li::before {
  content: '/';
  margin-right: 0.9rem;
}

.ilanel-breadcrumbs a:hover {
  color: var(--rg-ink);
}

.ilanel-breadcrumbs [aria-current='page'] {
  color: var(--rg-ink);
}

/* --- Product article ------------------------------------------------------ */

.rg-main {
  padding-bottom: 6rem;
}

/* .rg-article shares an element with .rg-shell, so it must not reset the
   horizontal padding — doing so clipped the product name off the page. */
.rg-article {
  padding-top: 7rem;
  padding-bottom: 9rem;
}

.rg-article__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr);
  gap: 8rem;
  align-items: start;
}

.rg-article__head {
  margin-bottom: 4.1rem;
}

/* The piece name: large, light serif — RG's signature move. */
.rg-product__name {
  margin: 0 0 1rem;
  font-family: var(--rg-serif);
  font-size: 5.6rem;
  font-weight: 400;
  line-height: 1.05;
  letter-spacing: 0.01em;
}

.rg-product__type {
  margin: 0;
  font-size: 1.2rem;
  font-weight: 400;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-article__content p {
  max-width: 60rem;
  margin: 0 0 2.2rem;
  font-size: 1.8rem;
  font-weight: 300;
  line-height: 1.35;
}

.rg-meta {
  display: flex;
  gap: 1.5rem;
  margin: 0 0 0.7rem;
  font-size: 1.3rem;
  font-weight: 300;
}

.rg-meta__label {
  min-width: 9rem;
  font-size: 1.1rem;
  font-weight: 400;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

/* RG's link style: uppercase, tracked, trailing slash, underline on hover. */
.rg-cta {
  margin: 3.5rem 0 0;
}

.rg-link {
  display: inline-block;
  font-size: 1.2rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  border-bottom: 1px solid transparent;
  padding-bottom: 0.3rem;
  transition: border-color 0.2s ease;
}

.rg-link:hover {
  border-bottom-color: var(--rg-ink);
}

/* --- Sections (Finishes, Downloads) --------------------------------------- */

.rg-section {
  padding: 5rem 0;
}

.rg-section--details {
  padding-bottom: 12rem;
}

.rg-section__label {
  display: block;
  margin-bottom: 4.1rem;
  font-size: 1.2rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-accent);
}

.rg-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4rem 8rem;
  padding-top: 2.5rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-section__title {
  max-width: 38rem;
  margin: 0;
  font-size: 2.2rem;
  font-weight: 300;
  line-height: 1.3;
  letter-spacing: 0.005em;
}

.rg-section__list {
  margin: 0;
  padding: 0;
  list-style: none;
  columns: 2;
  column-gap: 4rem;
}

.rg-section__list li {
  margin-bottom: 1.4rem;
  font-size: 1.4rem;
  font-weight: 300;
  break-inside: avoid;
}

.rg-section__list--links li {
  font-size: 1.2rem;
  font-weight: 400;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.rg-section__list--links a {
  border-bottom: 1px solid var(--rg-rule);
  padding-bottom: 0.3rem;
  transition: border-color 0.2s ease;
}

.rg-section__list--links a:hover {
  border-bottom-color: var(--rg-ink);
}

/* --- Range archive -------------------------------------------------------- */

.rg-main--archive {
  padding-top: 1rem;
}

.rg-range__header {
  margin-bottom: 4.5rem;
}

.rg-range__title {
  margin: 0 0 1.2rem;
  font-family: var(--rg-serif);
  font-size: 4.4rem;
  font-weight: 400;
  line-height: 1.1;
}

.rg-range__intro {
  max-width: 52rem;
}

.rg-range__intro p {
  margin: 0;
  font-size: 1.6rem;
  font-weight: 300;
  line-height: 1.4;
  color: #333;
}

/* Filters: accent label, hairline rule, wide-spaced terms. */
.rg-filters {
  margin-bottom: 4.5rem;
}

.rg-filters__label {
  display: block;
  margin-bottom: 1.2rem;
  padding-bottom: 1.2rem;
  border-bottom: 1px solid var(--rg-ink);
  font-size: 1.1rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-accent);
}

.rg-filters ul {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem 6rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rg-filters a {
  font-size: 1.3rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transition: opacity 0.18s ease;
}

.rg-filters a:hover {
  opacity: 0.5;
}

.rg-filters .is-current a {
  font-weight: 600;
}

/* --- Product grid --------------------------------------------------------- */

.rg-products {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5rem 3rem;
  margin: 0 0 8rem;
  padding: 0;
  list-style: none;
}

/* RG serve product tiles at 895x1023 — a portrait crop, not a square. */
.rg-product-card__media {
  background: var(--rg-tile);
  aspect-ratio: 895 / 1023;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.6rem;
  overflow: hidden;
}

.rg-products li:nth-child(3n + 2) .rg-product-card__media {
  background: var(--rg-tile-alt);
}

/* ILANEL's photography is in-situ interiors, not RG's cut-out product
   shots on white. `cover` fills the tile cleanly instead of leaving a
   landscape image floating in grey. Swap to `contain` with padding once
   the studio supplies cut-outs. */
.rg-product-card__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease, opacity 0.3s ease;
}

.rg-product-card a:hover .rg-product-card__media img {
  transform: scale(1.03);
  opacity: 0.9;
}

.rg-product-card__title {
  margin: 0 0 0.3rem;
  font-size: 1.3rem;
  font-weight: 400;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.rg-product-card__type {
  margin: 0 0 0.4rem;
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-product-card__price {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-product-card__price .woocommerce-Price-amount {
  font-weight: 300;
}

/* --- Footer --------------------------------------------------------------- */

.rg-footer {
  padding: 5rem 0 6rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-footer__inner {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 1.5rem;
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-footer p {
  margin: 0;
}

/* --- Responsive ----------------------------------------------------------- */

@media (max-width: 1100px) {
  .rg-article__row {
    grid-template-columns: 1fr;
    gap: 3.5rem;
  }

  .rg-products {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rg-product__name {
    font-size: 4.4rem;
  }
}

@media (max-width: 760px) {
  .rg-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .rg-section__list {
    columns: 1;
  }

  .rg-hero {
    height: 52vh;
    min-height: 30rem;
  }

  .rg-header__logo {
    font-size: 2.2rem;
  }
}

@media (max-width: 374px) {
  :root {
    --rg-shell: 2rem;
  }

  .rg-products {
    grid-template-columns: 1fr;
  }
}
